import{_ as a,o as s,c as t,a3 as c}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-47 — Xác nhận chuyển khoản thủ công (admin)","description":"","frontmatter":{"title":"SC-47 — Xác nhận chuyển khoản thủ công (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-47-xac-nhan-chuyen-khoan.md","filePath":"wireframes/admin/sc-47-xac-nhan-chuyen-khoan.md","lastUpdated":null}'),i={name:"wireframes/admin/sc-47-xac-nhan-chuyen-khoan.md"};function l(p,n,e,d,h,o){return s(),t("div",null,[...n[0]||(n[0]=[c('<h1 id="sc-47-—-xac-nhan-chuyen-khoan-thu-cong-admin" tabindex="-1">SC-47 — Xác nhận chuyển khoản thủ công (admin) <a class="header-anchor" href="#sc-47-—-xac-nhan-chuyen-khoan-thu-cong-admin" aria-label="Permalink to &quot;SC-47 — Xác nhận chuyển khoản thủ công (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/thanhtoan</span> <span class="wf-badge muted">Nguồn: docs/05 §3/§5 · docs/06 endpoints 59/60 + §5 · docs/08 BR-PAY-01/03/04 · docs/02 FR-PAY-03</span></p><p><strong>Ai xem màn này</strong>: ADMIN kế toán-vận hành — đối chiếu các khoản <strong>MANUAL_TRANSFER</strong> (chuyển khoản ngân hàng thủ công) người dùng đã nộp, chủ yếu là <strong>cọc đấu giá</strong>, trong <strong>SLA 2 giờ làm việc</strong>. <strong>Mục đích</strong>: queue PENDING + drawer đối chiếu <strong>nội dung bill <code>ANPHUC </code> + <code>&lt;paymentId&gt;</code></strong> và <strong>số tiền khớp từng đồng</strong> với mức kỳ vọng; xác nhận → payment SUCCESS + registration ACTIVE. Tiền vào hệ thống qua đây là tiền thật — không có &quot;xác nhận nhanh&quot;, mọi thứ phải khớp. <strong>Ví dụ số dùng trong bản vẽ</strong>: phiên <code>DGA-2026-0003</code> (căn CT1-B07.03, NOXH HP-380) khởi điểm <code>1.450.000.000 ₫</code> → cọc 5% = <code>72.500.000 ₫</code>; payment <code>pay_01J9ZM4T2W</code> của Vũ Thị Lan, bill đúng = <code>ANPHUC pay_01J9ZM4T2W</code>.</p><h2 id="_1-desktop-—-queue-cho-đoi-chieu-sla-2h" tabindex="-1">1. Desktop — queue chờ đối chiếu + SLA 2h <a class="header-anchor" href="#_1-desktop-—-queue-cho-đoi-chieu-sla-2h" aria-label="Permalink to &quot;1. Desktop — queue chờ đối chiếu + SLA 2h&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/thanhtoan?method=MANUAL_TRANSFER&amp;status=PENDING</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item">Đấu giá</span><span class="item active">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:12px;"><div class="wf-row between middle"><span class="wf-title lg">Thanh toán thủ công <span class="wf-callout">1</span></span><span class="wf-row middle" style="gap:8px;"><span class="wf-btn sm ghost">Xuất CSV</span><span class="wf-small wf-muted">SLA mục tiêu: xác nhận ≤ 2h giờ làm việc <span class="wf-callout">2</span></span></span></div><div class="wf-tabs"><span class="wf-tab active">Chờ đối chiếu (3)</span><span class="wf-tab">Đã xác nhận hôm nay (12)</span><span class="wf-tab">Lỗi đối soát RECON_FAILED (1)</span><span class="wf-tab">EXPIRED — intent quá 6h (4)</span></div><table class="wf-table"><thead><tr><th>Payment</th><th>Người nộp</th><th>Mục đích</th><th>Tiền kỳ vọng</th><th>Nội dung bill kỳ vọng</th><th>Tạo lúc</th><th>SLA 2h</th><th></th></tr></thead><tbody><tr><td><span class="wf-trace">pay_01J9ZK2M8Q</span></td><td>Hoàng Minh Đức<br><span class="wf-small">duc.hoang@example.com</span></td><td>DEPOSIT<br><span class="wf-small">DGA-2026-0003 · CT1-B07.03</span></td><td><span class="wf-money">72.500.000 ₫</span></td><td><span class="wf-trace">ANPHUC pay_01J9ZK2M8Q</span></td><td>10/10/2026 08:15<br><span class="wf-small">GMT+7</span></td><td><span class="wf-sla over">QUÁ HẠN 1h12</span></td><td><span class="wf-btn sm primary">Đối chiếu</span></td></tr><tr><td><span class="wf-trace">pay_01J9ZM4T2W</span></td><td>Vũ Thị Lan<br><span class="wf-small">lan.vu@example.com</span></td><td>DEPOSIT<br><span class="wf-small">DGA-2026-0003 · CT1-B07.03</span></td><td><span class="wf-money">72.500.000 ₫</span></td><td><span class="wf-trace">ANPHUC pay_01J9ZM4T2W</span></td><td>10/10/2026 10:40<br><span class="wf-small">GMT+7</span></td><td><span class="wf-sla soon">Còn 25 phút</span></td><td><span class="wf-btn sm primary">Đối chiếu</span></td></tr><tr><td><span class="wf-trace">pay_01J9ZN1Q7R</span></td><td>Đặng Quốc Bảo<br><span class="wf-small">bao.dang@example.com</span></td><td>DEPOSIT<br><span class="wf-small">DGA-2026-0004 · TB2-03.11</span></td><td><span class="wf-money">49.000.000 ₫</span></td><td><span class="wf-trace">ANPHUC pay_01J9ZN1Q7R</span></td><td>10/10/2026 11:02<br><span class="wf-small">GMT+7</span></td><td><span class="wf-sla ok">Còn 1h38</span></td><td><span class="wf-btn sm">Đối chiếu</span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">Sort mặc định: SLA gấp nhất trước — <b>quá hạn đội lên đầu</b> <span class="wf-callout">3</span></span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">›</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3/§5 · docs/08 BR-PAY · docs/06 endpoints 59/60)</div><ol><li><span class="num">1</span><span>Queue <b>chỉ MANUAL_TRANSFER</b> đang chờ (state INITIATED/PROCESSING) — VNPay không xuất hiện ở đây vì webhook tự đối soát (idempotent theo gatewayTxnRef). Filter purpose (DEPOSIT/SETTLEMENT/SUBSCRIPTION) + server-side paging qua <code>GET /admin/payments?status=&amp;purpose=</code>. <span class="ref">FR-PAY-02/03</span> <span class="ref">endpoint 59</span></span></li><li><span class="num">2</span><span><b>SLA 2h giờ làm việc</b> (BR-PAY-04): badge 3 mức — <code>ok</code> (còn &gt;30&#39;), <code>soon</code> (≤30&#39;, vàng), <code>over</code> (quá hạn, đỏ nhấp nháy). Quá hạn còn bắn alert vận hành. User phía SC-24 thấy chữ &quot;chờ ADMIN xác nhận ≤2h&quot;. <span class="ref">BR-PAY-04</span> <span class="ref">FR-STAT-01</span></span></li><li><span class="num">3</span><span><b>Quá hạn đội lên đầu</b> — queue là công cụ chạy SLA, không phải danh sách tĩnh. Cột &quot;Nội dung bill kỳ vọng&quot; hiện sẵn ở bảng để admin liếc nhanh khi đối chiếu sổ phụ ngân hàng nhiều dòng. <span class="ref">docs/05 §3</span></span></li><li><span class="num">4</span><span>Tab <b>EXPIRED</b>: intent quá 6h chưa được xác nhận → job chuyển EXPIRED, biến mất khỏi queue chờ; user tự tạo intent mới trong window nghiệp vụ (không giới hạn lần trước regDeadline). Admin không &quot;hồi sinh&quot; intent cũ. <span class="ref">BR-PAY-03</span> <span class="ref">BR-AU-07</span></span></li><li><span class="num">5</span><span>Mọi mutation màn này → <b>toast + audit log</b> (<code>PAYMENT_CONFIRM_MANUAL</code>/<code>PAYMENT_MARK_FAILED</code>, ghi confirmed_by, ip, traceId) — xem tại SC-49. <span class="ref">BR-PAY-04</span> <span class="ref">BR-ADM-01</span></span></li></ol></div><h2 id="_2-drawer-đoi-chieu-—-bill-thuc-te-vs-ky-vong-khop" tabindex="-1">2. Drawer đối chiếu — bill thực tế vs kỳ vọng (khớp) <a class="header-anchor" href="#_2-drawer-đoi-chieu-—-bill-thuc-te-vs-ky-vong-khop" aria-label="Permalink to &quot;2. Drawer đối chiếu — bill thực tế vs kỳ vọng (khớp)&quot;">​</a></h2><div class="wf"><div class="wf-row" style="align-items:flex-start;gap:0;"><div class="wf-grow" style="opacity:0.35;padding:16px;"><table class="wf-table"><thead><tr><th>Payment</th><th>Người nộp</th><th>Tiền kỳ vọng</th><th>SLA 2h</th></tr></thead><tbody><tr><td><span class="wf-trace">pay_01J9ZK2M8Q</span></td><td>Hoàng Minh Đức</td><td><span class="wf-money">72.500.000 ₫</span></td><td><span class="wf-sla over">QUÁ HẠN 1h12</span></td></tr><tr><td><span class="wf-trace">pay_01J9ZM4T2W</span></td><td>Vũ Thị Lan</td><td><span class="wf-money">72.500.000 ₫</span></td><td><span class="wf-sla soon">Còn 25 phút</span></td></tr></tbody></table><span class="wf-small">(bảng phía sau làm mờ — drawer trượt phải, đóng bằng ESC/nút ×, không mất vị trí scroll)</span></div><div class="wf-drawer wf-col" style="gap:10px;width:400px;"><div class="wf-row between middle"><span class="wf-title">Đối chiếu pay_01J9ZM4T2W</span><span class="wf-sla soon">SLA còn 25 phút</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">NGƯỜI NỘP</span><span class="wf-strong">Vũ Thị Lan · <span class="wf-trace">usr_01J8T4V2N6</span></span><span class="wf-small">lan.vu@example.com · 09xx-xxx-214 · KYC <span class="wf-badge ok">APPROVED</span></span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">BỐI CẢNH</span><span class="wf-small">DEPOSIT — cọc phiên <b>DGA-2026-0003</b> (CT1-B07.03 · NOXH HP-380 · khởi điểm 1.450.000.000 ₫)</span><span class="wf-small">Registration <span class="wf-trace">agr_01J9ZM4P03</span> · <span class="wf-badge warn">PENDING_DEPOSIT</span> · đóng ĐK 11/10/2026 09:00 (GMT+7) <span class="wf-callout">6</span></span></div><div class="wf-col" style="gap:4px;border-top:2px solid var(--wf-line-strong);padding-top:10px;"><span class="wf-title">Bảng đối chiếu <span class="wf-callout">7</span></span><div class="wf-row between"><span class="wf-small wf-muted">NỘI DUNG BILL</span><span class="wf-small">kỳ vọng: <span class="wf-trace">ANPHUC pay_01J9ZM4T2W</span></span></div><div class="wf-input filled" style="font-family:ui-monospace, Menlo, monospace;">ANPHUC pay_01J9ZM4T2W<span class="caret">✎</span></div><span class="wf-small wf-muted">Dán nội dung từ sổ phụ ngân hàng — hệ thống so khớp tự động <span class="wf-callout">8</span></span><div class="wf-row between" style="margin-top:6px;"><span class="wf-small wf-muted">SỐ TIỀN</span><span class="wf-small">kỳ vọng: <span class="wf-money">72.500.000 ₫</span></span></div><div class="wf-input filled"><span class="wf-money">72.500.000 ₫</span><span class="caret">✎</span></div><div class="wf-note" style="background:var(--wf-ok-soft);border-color:var(--wf-ok);color:var(--wf-ok);margin:4px 0 0;">✓ Khớp nội dung · ✓ Khớp từng đồng (chênh 0 ₫) — đủ điều kiện CONFIRM_MANUAL <span class="wf-callout">9</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Ghi chú đối chiếu (bắt buộc — số chứng từ ngân hàng, giờ nhận)</span><div class="wf-input filled">Sổ phụ VCB 10/10 số GD 88214077, tiền vào 11:05<span class="caret">✎</span></div></div><div class="wf-col" style="gap:8px;margin-top:4px;"><span class="wf-btn ok block">Xác nhận đã nhận tiền (CONFIRM_MANUAL) <span class="wf-callout" style="background:#fff;color:var(--wf-ok);">10</span></span><span class="wf-btn danger ghost block">Đánh dấu FAILED (không tìm thấy tiền trong sổ phụ)</span><span class="wf-small wf-center wf-muted">Intent tự EXPIRED lúc 16:40 nếu không xử lý (TTL 6h)</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">6</span><span>Bối cảnh đầy đủ để quyết định đúng: cọc của phiên nào, registration đang ở state gì, deadline đóng đăng ký — sát deadline thì ưu tiên xử lý (user đang chờ ACTIVE để kịp window). <span class="ref">UC-07 AF-1</span></span></li><li><span class="num">7</span><span><b>Đối chiếu 2 tiêu chí, cả hai bắt buộc</b> (BR-PAY-04): nội dung bill khớp mẫu hệ thống sinh = <code>ANPHUC </code> + <code>&lt;paymentId&gt;</code> VÀ số tiền khớp <b>từng đồng</b> với deposit_amount. Thiếu 1 trong 2 → không được confirm. <span class="ref">BR-PAY-04</span> <span class="ref">FR-PAY-03</span></span></li><li><span class="num">8</span><span>Admin <b>dán</b> nội dung/số tiền thực nhận từ sổ phụ (v1 không tích hợp bank feed) — hệ thống tự so và hiện kết quả khớp/lệch realtime khi gõ. Không có nút &quot;confirm bỏ qua đối chiếu&quot;. <span class="ref">docs/05 §5</span></span></li><li><span class="num">9</span><span>Trạng thái khớp: note xanh &quot;Khớp nội dung · Khớp từng đồng (chênh 0 ₫)&quot;. Tiền lệch dù 1 ₫ → xem mục 3 (RECON_FAILED, không auto-apply). <span class="ref">BR-PAY-01</span></span></li><li><span class="num">10</span><span><b>CONFIRM_MANUAL</b> → modal xác nhận (mục 3) → <code>PATCH /admin/payments/{id}</code>: payment SUCCESS + registration <b>ACTIVE</b> + cấp pseudonym + NTF user, cùng event luồng webhook. Ghi <code>confirmed_by</code> = admin hiện tại + audit. <span class="ref">endpoint 60</span> <span class="ref">docs/05 §5</span></span></li></ol></div><h2 id="_3-modal-xac-nhan-nhanh-lech-recon-failed" tabindex="-1">3. Modal xác nhận + nhánh lệch (RECON_FAILED) <a class="header-anchor" href="#_3-modal-xac-nhan-nhanh-lech-recon-failed" aria-label="Permalink to &quot;3. Modal xác nhận + nhánh lệch (RECON_FAILED)&quot;">​</a></h2><div class="wf"><div class="wf-row" style="gap:16px;align-items:flex-start;flex-wrap:wrap;"><div class="wf-col" style="flex:1;min-width:320px;"><span class="wf-state-label">MODAL XÁC NHẬN (sau khi bấm CONFIRM_MANUAL)</span><div class="wf-modal-overlay" style="padding:16px;"><div class="wf-modal"><div class="head">Xác nhận đã nhận 72.500.000 ₫?</div><div class="wf-lines" style="margin:8px 0;"><div class="wf-row between"><span class="wf-text">Payment</span><span class="wf-trace">pay_01J9ZM4T2W</span></div><div class="wf-row between"><span class="wf-text">Người nộp</span><span class="wf-strong">Vũ Thị Lan</span></div><div class="wf-row between"><span class="wf-text">Đối chiếu</span><span class="wf-ok-text">✓ nội dung · ✓ số tiền (chênh 0 ₫)</span></div></div><div class="wf-note">Hệ quả: payment → <b>SUCCESS</b> · registration agr_01J9ZM4P03 → <b>ACTIVE</b> (cấp pseudonym TV-XXXX) · gửi thông báo cho user · audit <code>PAYMENT_CONFIRM_MANUAL</code> ghi tên bạn. <span class="wf-callout">11</span></div><div class="wf-row" style="margin-top:10px;"><span class="wf-btn" style="flex:1;">Quay lại</span><span class="wf-btn ok" style="flex:1;">XÁC NHẬN</span></div></div></div></div><div class="wf-col" style="flex:1;min-width:320px;"><span class="wf-state-label">DRAWER — SỐ TIỀN LỆCH (72.000.000 vs 72.500.000)</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-small wf-muted">SỐ TIỀN</span><span class="wf-small">kỳ vọng: <span class="wf-money">72.500.000 ₫</span></span></div><div class="wf-input error filled"><span class="wf-money">72.000.000 ₫</span><span class="caret">✎</span></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:0;">✗ Lệch −500.000 ₫ — không khớp từng đồng. <b>RECON_FAILED: không auto-apply dưới mọi hình thức.</b> <span class="wf-callout danger">12</span></div><span class="wf-btn disabled block">Xác nhận đã nhận tiền (khóa khi lệch)</span><span class="wf-small">Xử lý: CS liên hệ user — (a) nộp bổ sung 500.000 ₫ đúng nội dung bill rồi đối chiếu lại, hoặc (b) <b>Đánh dấu FAILED</b> (lý do bắt buộc) để user tạo intent mới; tiền đã chuyển sai hoàn theo quy trình ngân hàng ngoài hệ thống, có biên bản ops.</span></div></div><span class="wf-state-label">DRAWER — NỘI DUNG BILL SAI</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-input error filled" style="font-family:ui-monospace, Menlo, monospace;">CK tien coc dau gia<span class="caret">✎</span></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:0;">✗ Không chứa <span class="wf-trace">ANPHUC pay_01J9ZM4T2W</span> — không xác định được khoản này của payment nào. Nút xác nhận khóa; hướng dẫn CS yêu cầu user chuyển lại đúng nội dung (intent cũ còn TTL thì dùng lại được). <span class="wf-callout danger">13</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Modal nêu <b>đủ 3 hệ quả</b> (payment/registration/audit) trước khi bấm — confirm rồi vẫn sửa được? Không: sau SUCCESS chỉ còn đường đối soát offline (BR-PAY-06/07), nên modal là chốt chặn cuối. Đang gửi → nút loading disabled. <span class="ref">docs/05 §1.3</span></span></li><li><span class="num">12</span><span><b>Lệch tiền ⇒ RECON_FAILED (422 nếu cố gọi API)</b> — hệ thống không tự cấn trừ, không &quot;xác nhận một phần&quot;. Nút confirm khóa cứng bằng cả FE lẫn BE (defense in depth). <span class="ref">BR-PAY-01</span></span></li><li><span class="num">13</span><span>Sai nội dung bill = không thể gán tiền vào payment — kể cả khi số tiền đúng. Đây là lỗi phổ biến nhất của chuyển khoản thủ công; drawer luôn chỉ bước tiếp theo cho CS thay vì chỉ báo lỗi. <span class="ref">BR-PAY-04</span></span></li></ol></div><h2 id="_4-duplicate-no-op-·-empty-·-loading-·-error" tabindex="-1">4. Duplicate no-op · Empty · Loading · Error <a class="header-anchor" href="#_4-duplicate-no-op-·-empty-·-loading-·-error" aria-label="Permalink to &quot;4. Duplicate no-op · Empty · Loading · Error&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-2"><div class="wf-col"><span class="wf-state-label">DUPLICATE — 2 ADMIN CÙNG XÁC NHẬN (200 NO-OP)</span><div class="wf-card"><div class="pad wf-col"><div class="wf-toast info"><b>Giao dịch này đã được xử lý trước đó</b> bởi admin.tran@anphuc.vn lúc 10:52 — không có thay đổi nào được ghi (no-op). <span class="wf-callout">14</span></div><span class="wf-small">Drawer tự refresh sang chế độ read-only: state SUCCESS, confirmed_by admin.tran, dòng tiền không nhân đôi. Không toast đỏ — đây không phải lỗi, là race bình thường giữa 2 ops.</span></div></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — QUEUE SẠCH</span><div class="wf-empty"><b>Không có giao dịch thủ công nào chờ xác nhận</b><br><span class="wf-small">Queue đang sạch — SLA 2h được đảm bảo. Các giao dịch VNPay tự đối soát qua webhook, không hiển thị ở đây.</span><br><span class="wf-small">Đề xuất: kiểm tra tab &quot;Lỗi đối soát RECON_FAILED (1)&quot; — có 1 khoản cần xử lý thủ công.</span></div></div><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:34px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><span class="wf-small">Skeleton tabs + 3 dòng queue; drawer (nếu đang mở) skeleton khối đối chiếu — không hiện nút confirm tới khi tải xong dữ liệu kỳ vọng.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC QUEUE</span><div class="wf-error-box"><b>Không tải được danh sách giao dịch</b><br><span class="wf-small">Tiền có thể vẫn đang chờ — thử lại ngay, nếu lỗi kéo dài báo kỹ thuật kèm mã truy vết. Không khoản nào bị mất vì lỗi hiển thị (intent còn TTL 6h).</span><br><span class="wf-trace">traceId: e51b77d2-9c04-4a8f</span><div style="margin-top:10px;"><span class="wf-btn">Thử lại</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">14</span><span><b>Duplicate → 200 no-op + toast info &quot;đã xử lý trước đó&quot;</b> (PAYMENT_DUPLICATE) — đúng behavior matrix docs/05 §5; server idempotent, FE không retry, không hiện lỗi. <span class="ref">docs/05 §5</span> <span class="ref">docs/06 §2</span></span></li><li><span class="num">15</span><span>Thành công: toast ok <b>&quot;Đã xác nhận thanh toán pay_01J9ZM4T2W — registration của Vũ Thị Lan chuyển ACTIVE, đã gửi thông báo&quot;</b>, dòng biến mất khỏi queue chờ, SLA stop. Thất bại (MARK_FAILED): reason bắt buộc 5–500 ký tự + audit, user nhận NTF hướng dẫn tạo intent mới. <span class="ref">endpoint 60</span> <span class="ref">FR-NTF-05</span></span></li><li><span class="num">16</span><span>4-state bắt buộc: Loading (skeleton) → Empty (queue sạch + gợi ý tab lỗi) → Error (message + traceId + Thử lại) → Data (mục 1–2). <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-47" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-47 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-47" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-47&quot;">​</a></h2><ul><li>[ ] Queue: 4 tabs (chờ / đã xác nhận hôm nay / RECON_FAILED / EXPIRED) + 8 cột, SLA badge 3 mức (ok/soon/over — over nhấp nháy)</li><li>[ ] Drawer đối chiếu: khối người nộp · khối bối cảnh (phiên/registration/deadline) · bảng đối chiếu 2 tiêu chí (nội dung + số tiền) · ghi chú bắt buộc · 2 nút (CONFIRM_MANUAL ok / MARK_FAILED danger)</li><li>[ ] 3 biến thể đối chiếu: khớp (note xanh + confirm enabled) · lệch tiền (note đỏ + confirm khóa + 2 hướng xử lý) · sai nội dung bill (note đỏ + hướng dẫn CS)</li><li>[ ] Nội dung bill render dạng monospace; mẫu hệ thống ghi rõ &quot;ANPHUC&quot; + paymentId — không viết tắt, không xuống dòng giữa chừng</li><li>[ ] Modal xác nhận nêu đủ 3 hệ quả (payment SUCCESS / registration ACTIVE / audit) + loading state</li><li>[ ] Toast đủ 4: ok xác nhận · info duplicate no-op &quot;đã xử lý trước đó&quot; · danger RECON_FAILED 422 · danger mark-failed thành công (audit)</li><li>[ ] 4-state: skeleton / empty / error+traceId / data; empty có gợi ý kiểm tra tab RECON_FAILED</li><li>[ ] Responsive note: desktop-priority; ≤768px drawer full-width trượt từ dưới, bảng cuộn ngang ưu tiên cột SLA + nút Đối chiếu</li><li>[ ] Không emoji icon production (✓/✗ trong wireframe là placeholder — thay icon set thật); tiền <code>72.500.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> + GMT+7</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const f=a(i,[["render",l]]);export{g as __pageData,f as default};
